<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\Accessor\UserFederatedIdentitySubjectAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserFederatedIdentitySubjectAccessor trait.
 *
 * Covers null default, string/VO assignment via withSubject,
 * getSubject/subject accessors, and isSubjectChanged with/without original.
 */
class UserFederatedIdentitySubjectAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withSubject creates a new instance with the Subject set
     * from a string value, and getSubject returns the primitive string.
     */
    public function testWithSubjectFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserFederatedIdentitySubjectAccessorUnitTest();

        // Act
        $result = $holder->withSubject('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getSubject());
    }
    /**
     * Asserts that withsubject has access to the value object
     * from a string value, and getSubject returns the primitive string.
     */
    public function testWithSubjectFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserFederatedIdentitySubjectAccessorUnitTest();

        // Act
        $result = $holder->withSubject('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->subject()->value());
    }
    public function testChangedSubject(): void
    {
        // Arrange
        $holder = new ImplWithUserFederatedIdentitySubjectAccessorUnitTest()->withSubject('one');
        $original = $holder->withSubject('one');
        $same = $holder->withSubject('one');
        $modified = $holder->withSubject('other');

        // Act
        $withSame = $original->isSubjectChanged($same);
        $withDiferent = $original->isSubjectChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserFederatedIdentitySubjectAccessorUnitTest
{
    use UserFederatedIdentitySubjectAccessor;
}
